<script lang="ts">
  import { api } from './api';
  import SpecialIdentityControls from './SpecialIdentityControls.svelte';
  import type { Club, ClubMember, ContestTemplate, Event, EventParticipant, EventScore, ManagedCallsign } from './types';

  let { events, clubs, templates, administrator, refresh }: { events: Event[]; clubs: Club[]; templates: ContestTemplate[]; administrator: boolean; refresh: () => Promise<void> } = $props();
  let selectedEventId = $state<string | null>(null);
  let loadedEventId = $state<string | null>(null);
  let composerOpen = $state(false);
  let editingEventId = $state<string | null>(null);
  let clubId = $state(''); let name = $state(''); let templateId = $state(''); let specialCallsign = $state(''); let start = $state(''); let end = $state(''); let status = $state('draft'); let config = $state<Record<string, string>>({});
  let working = $state(false); let error = $state(''); let eventSearch = $state(''); let eventStatusFilter = $state('all'); let configuredTemplateId = $state('');
  let participants = $state<EventParticipant[]>([]); let identities = $state<ManagedCallsign[]>([]); let clubMembers = $state<ClubMember[]>([]); let score = $state<EventScore | null>(null); let detailLoading = $state(false);
  let participantId = $state<string | null>(null); let participantUserId = $state(''); let participantIdentityId = $state(''); let participantRole = $state('operator'); let participantStatus = $state('active'); let participantStation = $state(''); let participantBand = $state(''); let participantMode = $state('');
  let manageableClubs = $derived(clubs.filter((club) => club.can_manage));
  let selectedEvent = $derived(events.find((event) => event.id === selectedEventId));
  let selectedTemplate = $derived(templates.find((template) => template.id === templateId));
  let eventTemplate = $derived(templates.find((template) => template.id === selectedEvent?.contest_template_id));
  let assignableIdentities = $derived(identities.filter((identity) => identity.club_id === selectedEvent?.club_id && (identity.event_id === null || identity.event_id === selectedEventId)));
  let specialIdentity = $derived(assignableIdentities.find((identity) => identity.identity_type === 'special' && identity.event_id === selectedEventId));
  let filteredEvents = $derived(events.filter((event) => { const query = eventSearch.trim().toLowerCase(); return (!query || `${event.name} ${event.contest_name} ${event.special_callsign || ''}`.toLowerCase().includes(query)) && (eventStatusFilter === 'all' || event.status === eventStatusFilter); }));
  $effect(() => { if (!manageableClubs.some((club) => club.id === clubId)) clubId = manageableClubs[0]?.id || ''; });
  $effect(() => { if (!selectedEventId || !events.some((event) => event.id === selectedEventId)) selectedEventId = events[0]?.id || null; });
  $effect(() => { if (selectedEvent && !composerOpen && loadedEventId !== selectedEvent.id) { loadedEventId = selectedEvent.id; void selectEvent(selectedEvent); } });
  $effect(() => { if (templateId !== configuredTemplateId && selectedTemplate) { configuredTemplateId = templateId; config = Object.fromEntries(Object.keys(selectedTemplate.required_fields).map((key) => [key, ''])); } else if (templateId !== configuredTemplateId) { configuredTemplateId = templateId; config = {}; } });
  function canManage(event: Event | undefined): boolean { return !!event && manageableClubs.some((club) => club.id === event.club_id); }
  function clubName(id: string): string { return clubs.find((club) => club.id === id)?.name || 'Unknown club'; }
  function localDateTime(value: string): string { const date = new Date(value); const pad = (part: number) => String(part).padStart(2, '0'); return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}`; }
  function clearParticipantForm() { participantId = null; participantUserId = clubMembers.find((member) => member.membership_status === 'active')?.user_id || ''; participantIdentityId = assignableIdentities.find((identity) => identity.status === 'active' && identity.verification_status === 'verified')?.id || ''; participantRole = 'operator'; participantStatus = 'active'; participantStation = participantBand = participantMode = ''; }
  function resetComposer() { composerOpen = false; editingEventId = null; name = specialCallsign = start = end = ''; templateId = ''; status = 'draft'; config = {}; }
  function editEvent(event: Event) { composerOpen = true; editingEventId = event.id; selectedEventId = event.id; clubId = event.club_id; name = event.name; templateId = event.contest_template_id || ''; specialCallsign = event.special_callsign || ''; start = localDateTime(event.starts_at); end = localDateTime(event.ends_at); status = event.status; config = Object.fromEntries(Object.entries(event.contest_config || {}).map(([key, value]) => [key, String(value)])); }
  function newEvent() { resetComposer(); composerOpen = true; }
  async function run(work: () => Promise<void>) { working = true; error = ''; try { await work(); } catch (cause) { error = (cause as Error).message; } finally { working = false; } }
  async function selectEvent(event: Event) { selectedEventId = event.id; loadedEventId = event.id; composerOpen = false; detailLoading = true; error = ''; try { [participants, identities, clubMembers, score] = await Promise.all([api<EventParticipant[]>(`/api/v1/events/${event.id}/participants`), api<ManagedCallsign[]>('/api/v1/identities'), api<ClubMember[]>(`/api/v1/clubs/${event.club_id}/members`), api<EventScore>(`/api/v1/events/${event.id}/score`)]); clearParticipantForm(); } catch (cause) { error = (cause as Error).message; } finally { detailLoading = false; } }
  async function saveEvent() { await run(async () => { const event = await api<Event>(editingEventId ? `/api/v1/events/${editingEventId}` : '/api/v1/events', { method: editingEventId ? 'PATCH' : 'POST', body: JSON.stringify({ club_id: clubId, name, contest_name: selectedTemplate?.name || '', special_callsign: specialCallsign || null, starts_at: new Date(start).toISOString(), ends_at: new Date(end).toISOString(), status, contest_template_id: templateId || null, contest_config: config }) }); await refresh(); resetComposer(); await selectEvent(event); }); }
  async function setStatus(nextStatus: string) { if (!selectedEvent) return; await run(async () => { await api(`/api/v1/events/${selectedEvent.id}/status`, { method: 'PATCH', body: JSON.stringify({ status: nextStatus }) }); await refresh(); await selectEvent(selectedEvent); }); }
  function editParticipant(participant: EventParticipant) { participantId = participant.id; participantUserId = participant.user_id; participantIdentityId = participant.callsign_id; participantRole = participant.role; participantStatus = participant.status; participantStation = participant.station_label; participantBand = participant.band || ''; participantMode = participant.mode || ''; }
  async function saveParticipant() { const member = clubMembers.find((item) => item.user_id === participantUserId); if (!selectedEvent || !member) return; await run(async () => { const base = `/api/v1/events/${selectedEvent.id}/participants`; await api<EventParticipant>(participantId ? `${base}/${participantId}` : base, { method: participantId ? 'PATCH' : 'POST', body: JSON.stringify({ user_id: participantUserId, callsign_id: participantIdentityId, operator_callsign: member.callsign, role: participantRole, status: participantStatus, starts_at: null, ends_at: null, station_label: participantStation, band: participantBand || null, mode: participantMode || null }) }); await selectEvent(selectedEvent); }); }
  async function decideSpecialIdentity(decision: string) { if (!specialIdentity || !selectedEvent) return; await run(async () => { await api(`/api/v1/identities/${specialIdentity.id}/status`, { method: 'PATCH', body: JSON.stringify({ decision }) }); await selectEvent(selectedEvent); }); }
</script>

<section class="operations-workspace">
  <aside class="operation-directory">
    <div class="section-head"><div><p class="eyebrow">OPERATIONS</p><h2>Contest calendar</h2></div><button onclick={newEvent} disabled={!manageableClubs.length}>NEW</button></div>
    <p class="form-help">Select an operation to prepare its identity, roster, station assignments, and score.</p>
    <div class="directory-tools"><input aria-label="Search events" placeholder="Search operations" bind:value={eventSearch} /><select aria-label="Filter events by status" bind:value={eventStatusFilter}><option value="all">All states</option>{#each ['draft', 'scheduled', 'active', 'completed', 'cancelled'] as option}<option value={option}>{option}</option>{/each}</select></div>
    {#each filteredEvents as event}<button class:selected={event.id === selectedEventId} class="operation-row" onclick={() => selectEvent(event)}><span><b>{event.name}</b><small>{clubName(event.club_id)} · {new Date(event.starts_at).toLocaleDateString()}</small></span><em>{event.status}</em></button>{:else}<p class="empty">No operations match these filters.</p>{/each}
  </aside>
  <main class="operation-detail">
    {#if composerOpen}
      <form class="operation-composer" onsubmit={(event) => { event.preventDefault(); void saveEvent(); }}>
        <div class="section-head"><div><p class="eyebrow">{editingEventId ? 'EDIT OPERATION' : 'NEW OPERATION'}</p><h2>{editingEventId ? selectedEvent?.name : 'Plan an operation'}</h2></div><button type="button" class="secondary" onclick={resetComposer}>CLOSE</button></div><p class="form-help">A contest template makes scoring and exchanges explicit. A general operation stays useful for Field Day-style coordination.</p>
        <div class="form-columns"><label>Club<select bind:value={clubId} required>{#each manageableClubs as club}<option value={club.id}>{club.name}</option>{/each}</select></label><label>Operation name<input maxlength="150" bind:value={name} required /></label><label>Contest template<select bind:value={templateId}><option value="">General / non-contest event</option>{#each templates as template}<option value={template.id}>{template.icon} {template.organization} · {template.name}</option>{/each}</select></label><label>Special callsign<input maxlength="16" bind:value={specialCallsign} /><small>Requires a managed identity before it can be used.</small></label><label>Starts<input type="datetime-local" bind:value={start} required /></label><label>Ends<input type="datetime-local" bind:value={end} required /></label><label>Initial state<select bind:value={status}>{#each ['draft', 'scheduled', 'active'] as option}<option value={option}>{option}</option>{/each}</select></label></div>
        {#if selectedTemplate}<aside class="template-card"><b>{selectedTemplate.icon} {selectedTemplate.name}</b><p>{selectedTemplate.description}</p><small>{String(selectedTemplate.scoring_rules.formula || 'Template scoring')} · catalog v{selectedTemplate.definition_version}</small>{#if selectedTemplate.rules_url}<a href={selectedTemplate.rules_url} target="_blank" rel="noreferrer">Open current rules ↗</a>{/if}</aside>{#each Object.entries(selectedTemplate.required_fields) as [key, field]}<label>{key.replaceAll('_', ' ')}{#if field.required}<sup>required</sup>{/if}{#if field.options}<select bind:value={config[key]} required={field.required}><option value="">Select…</option>{#each field.options as option}<option value={option}>{option}</option>{/each}</select>{:else}<input bind:value={config[key]} required={field.required} />{/if}{#if field.description}<small>{field.description}</small>{/if}</label>{/each}{/if}
        {#if error}<p class="error">{error}</p>{/if}<div class="actions"><button disabled={working || !clubId}>{working ? 'SAVING…' : editingEventId ? 'SAVE OPERATION' : 'CREATE OPERATION'}</button></div>
      </form>
    {:else if selectedEvent}
      <SpecialIdentityControls event={selectedEvent} identity={specialIdentity} administrator={administrator} canManage={canManage(selectedEvent)} changed={() => selectEvent(selectedEvent!)} />
      <div class="operation-header"><div><p class="eyebrow">{clubName(selectedEvent.club_id)} / {eventTemplate?.organization || 'CLUB OPERATION'}</p><h1>{selectedEvent.name}</h1><p>{eventTemplate?.name || 'General club operation'} · {new Date(selectedEvent.starts_at).toLocaleString()} → {new Date(selectedEvent.ends_at).toLocaleString()}</p></div><span class="status-badge">{selectedEvent.status}</span></div>
      {#if error}<p class="error">{error}</p>{/if}{#if canManage(selectedEvent)}<div class="operation-actions"><button onclick={() => editEvent(selectedEvent)}>EDIT PLAN</button>{#if selectedEvent.status === 'draft'}<button onclick={() => setStatus('scheduled')}>SCHEDULE</button>{/if}{#if !['active', 'completed', 'cancelled'].includes(selectedEvent.status)}<button onclick={() => setStatus('active')}>ACTIVATE</button>{/if}{#if selectedEvent.status === 'active'}<button onclick={() => setStatus('completed')}>COMPLETE</button>{/if}{#if !['completed', 'cancelled'].includes(selectedEvent.status)}<button class="danger" onclick={() => setStatus('cancelled')}>CANCEL</button>{/if}</div>{/if}
      {#if detailLoading}<p class="empty">Loading operation records…</p>{:else}<div class="operation-metrics"><article><small>QSOs logged</small><b>{score?.qso_count ?? 0}</b></article><article><small>Score</small><b>{score?.total_points ?? 0}</b></article><article><small>Duplicates held</small><b>{score?.duplicate_count ?? 0}</b></article><article><small>Assigned operators</small><b>{participants.length}</b></article></div>{/if}
      <div class="operation-panels"><section class="detail-card"><p class="eyebrow">IDENTITY</p><h3>{specialIdentity ? specialIdentity.callsign : selectedEvent.special_callsign || 'Club operating identity'}</h3>{#if specialIdentity}<p>{specialIdentity.status} · verification {specialIdentity.verification_status}</p>{#if administrator && specialIdentity.verification_status === 'pending'}<div class="actions"><button onclick={() => decideSpecialIdentity('approve')}>APPROVE</button><button class="danger" onclick={() => decideSpecialIdentity('reject')}>REJECT</button></div>{/if}{:else}<p class="form-help">No special identity is attached. Club or personal identities can be assigned to the roster.</p>{/if}</section><section class="detail-card"><p class="eyebrow">RULES &amp; CONFIGURATION</p><h3>{eventTemplate?.name || 'General operation'}</h3>{#if Object.keys(selectedEvent.contest_config || {}).length}<dl>{#each Object.entries(selectedEvent.contest_config) as [key, value]}<div><dt>{key.replaceAll('_', ' ')}</dt><dd>{String(value)}</dd></div>{/each}</dl>{:else}<p class="form-help">No contest-specific configuration.</p>{/if}</section></div>
      <section class="roster-workspace"><div class="section-head"><div><p class="eyebrow">ROSTER &amp; STATIONS</p><h2>Operating assignments</h2></div><b>{participants.length} assigned</b></div><div class="roster-layout"><div>{#each participants as participant}<article class="assignment"><span><b>{participant.operator_callsign} → {participant.operating_callsign}</b><small>{participant.role} · {participant.station_label || 'Station not labelled'} · {participant.band || 'all bands'} · {participant.mode || 'all modes'}</small></span>{#if canManage(selectedEvent)}<button class="secondary" onclick={() => editParticipant(participant)}>EDIT</button>{/if}</article>{:else}<p class="empty">No one is assigned yet. Add station responsibility before the operation begins.</p>{/each}</div>{#if canManage(selectedEvent)}<form class="assignment-form" onsubmit={(event) => { event.preventDefault(); void saveParticipant(); }}><h3>{participantId ? 'Edit assignment' : 'Assign operator'}</h3><label>Operator<select bind:value={participantUserId} required>{#each clubMembers.filter((member) => member.membership_status === 'active') as member}<option value={member.user_id}>{member.callsign} · {member.role}</option>{/each}</select></label><label>Operating identity<select bind:value={participantIdentityId} required>{#each assignableIdentities.filter((identity) => identity.status === 'active' && identity.verification_status === 'verified') as identity}<option value={identity.id}>{identity.callsign} · {identity.identity_type}</option>{/each}</select></label><div class="form-columns compact"><label>Role<select bind:value={participantRole}>{#each ['operator', 'coordinator', 'logger', 'observer'] as item}<option value={item}>{item}</option>{/each}</select></label><label>Status<select bind:value={participantStatus}>{#each ['pending', 'invited', 'active', 'suspended', 'withdrawn', 'completed'] as item}<option value={item}>{item}</option>{/each}</select></label><label>Station label<input maxlength="80" bind:value={participantStation} /></label><label>Band<input maxlength="16" placeholder="Optional, e.g. 20m" bind:value={participantBand} /></label><label>Mode<input maxlength="24" placeholder="Optional, e.g. DIGITAL" bind:value={participantMode} /></label></div><div class="actions">{#if participantId}<button type="button" class="secondary" onclick={clearParticipantForm}>CANCEL EDIT</button>{/if}<button disabled={working || !participantUserId || !participantIdentityId}>{participantId ? 'SAVE ASSIGNMENT' : 'ASSIGN OPERATOR'}</button></div></form>{/if}</div></section>
    {:else}<div class="empty-state"><h2>Choose an operation</h2><p>Open an operation from the calendar, or create a new one for a club activity.</p><button onclick={newEvent} disabled={!manageableClubs.length}>PLAN AN OPERATION</button></div>{/if}
  </main>
</section>

<style>
  .operations-workspace { display:grid; grid-template-columns:minmax(260px, .7fr) minmax(0, 2fr); gap:18px; align-items:start; }.operation-directory, .operation-detail { border:1px solid var(--line); border-radius:14px; background:var(--panel); padding:18px; }.operation-directory { position:sticky; top:18px; max-height:calc(100vh - 36px); overflow:auto; }.section-head { display:flex; justify-content:space-between; gap:12px; align-items:center; }.section-head h2, h1, h3 { margin:0; }.eyebrow { color:var(--cyan); letter-spacing:.12em; font-size:.72rem; margin:0 0 4px; }.form-help, small { color:var(--muted); }.directory-tools { display:grid; grid-template-columns:minmax(0,1fr) auto; gap:8px; margin:16px 0 10px; }.operation-row { width:100%; text-align:left; display:flex; justify-content:space-between; gap:10px; background:transparent; border:1px solid transparent; color:var(--text); padding:12px 8px; border-radius:9px; }.operation-row:hover, .operation-row.selected { background:var(--chip); border-color:var(--line); }.operation-row span { display:grid; gap:4px; }.operation-row em { color:var(--muted); font-size:.74rem; font-style:normal; text-transform:uppercase; }.operation-header { display:flex; justify-content:space-between; gap:20px; align-items:start; }.operation-header h1 { font-size:clamp(1.5rem, 3vw, 2.35rem); }.status-badge { border-radius:999px; padding:6px 10px; background:var(--chip); color:var(--cyan); text-transform:uppercase; font-size:.75rem; }.operation-actions, .actions { display:flex; flex-wrap:wrap; gap:8px; margin:18px 0; }.operation-metrics { display:grid; grid-template-columns:repeat(4, minmax(0,1fr)); gap:10px; }.operation-metrics article, .detail-card, .roster-workspace, .operation-composer { border:1px solid var(--line); border-radius:10px; padding:14px; background:color-mix(in srgb, var(--panel) 82%, var(--chip)); }.operation-metrics small { display:block; }.operation-metrics b { display:block; font-size:1.5rem; margin-top:4px; }.operation-panels { display:grid; grid-template-columns:repeat(2, minmax(0,1fr)); gap:12px; margin:12px 0; }.detail-card h3 { margin:5px 0; }.detail-card dl { margin:12px 0 0; display:grid; gap:6px; }.detail-card dl div { display:flex; justify-content:space-between; gap:12px; }.detail-card dt { color:var(--muted); text-transform:capitalize; }.detail-card dd { margin:0; text-align:right; }.roster-workspace { margin-top:12px; }.roster-layout { display:grid; grid-template-columns:minmax(0,1fr) minmax(290px,.85fr); gap:16px; margin-top:12px; }.assignment { display:flex; justify-content:space-between; align-items:center; gap:12px; padding:12px 0; border-bottom:1px solid var(--line); }.assignment span { display:grid; gap:4px; }.assignment-form, .operation-composer { display:grid; gap:10px; align-content:start; } label { display:grid; gap:5px; }.form-columns { display:grid; grid-template-columns:repeat(2, minmax(0,1fr)); gap:10px; }.template-card { border-left:3px solid var(--cyan); padding:10px 12px; background:var(--chip); display:grid; gap:5px; }.template-card p { margin:0; }.template-card a { color:var(--cyan); }.error { color:var(--red); padding:10px; border-radius:8px; background:color-mix(in srgb, var(--red) 12%, transparent); }.empty, .empty-state { color:var(--muted); padding:20px 0; }.empty-state { display:grid; gap:10px; justify-items:start; }.empty-state h2, .empty-state p { margin:0; } @media (max-width:1050px) { .operations-workspace { grid-template-columns:240px minmax(0,1fr); }.operation-metrics { grid-template-columns:repeat(2,1fr); }.roster-layout { grid-template-columns:1fr; } } @media (max-width:760px) { .operations-workspace { grid-template-columns:1fr; }.operation-directory { position:static; max-height:none; }.operation-panels, .form-columns { grid-template-columns:1fr; }.directory-tools { grid-template-columns:1fr; } }
</style>
